  onCollapse?: () => void;
}

export const TreePanel: React.FC<TreePanelProps> = ({ onCollapse }) => {
  const storeState = useTimelineStore();
  const cp = storeState.activeCheckpoint || (storeState.checkpoints.length > 0 ? storeState.checkpoints[0] : null);
